    if (real !== root && !real.startsWith(`${root}${path.sep}`)) throw new DeliverError(`contract escapes project: ${rel}`, 66);
    if (!fs.statSync(real).isFile()) throw new DeliverError(`contract is not a regular file: ${rel}`, 66);
